def _column_values(table, values):
    return {key: value for key, value in values.items() if key in table.c}


def upgrade():
    bind = op.get_bind()
    meta = sa.MetaData()
    subjects = sa.Table("subjects", meta, autoload_with=bind)
    chapters = sa.Table("chapters", meta, autoload_with=bind)
    canonical = sa.Table("syllabus_chapters", meta, autoload_with=bind)
    notes = sa.Table("notes", meta, autoload_with=bind)
    questions = sa.Table("questions", meta, autoload_with=bind)

    sid = bind.execute(sa.select(subjects.c.id).where(subjects.c.slug == "ap_history")).scalar_one()
    chapter_ids = {}
    canonical_ids = {}
    note_hashes = {}

    for number, addition in ENRICHMENTS.items():
        chapter_id = bind.execute(sa.select(chapters.c.id).where(
            chapters.c.subject_id == sid, chapters.c.chapter_num == number
        )).scalar_one()
        canonical_id = bind.execute(sa.select(canonical.c.id).where(
            canonical.c.subject_id == sid, canonical.c.chapter_num == number
        )).scalar_one()
        note = bind.execute(sa.select(notes).where(notes.c.chapter_id == chapter_id).order_by(notes.c.section_num)).mappings().first()
        if note is None:
            raise RuntimeError(f"Chapter {number} note is missing")
        original = note["body_te"] or ""
        if MARKER in original:
            raise RuntimeError(f"Chapter {number} already contains APSCHE enrichment marker")
        original_hash = hashlib.sha256(original.encode("utf-8")).hexdigest()
        updated = original + "\n\n" + addition
        if not updated.startswith(original) or hashlib.sha256(updated[:len(original)].encode("utf-8")).hexdigest() != original_hash:
            raise RuntimeError(f"Chapter {number} source-preservation guard failed")
        bind.execute(notes.update().where(notes.c.id == note["id"]).values(body_te=updated))
        chapter_ids[number] = chapter_id
        canonical_ids[number] = canonical_id
        note_hashes[number] = original_hash

    existing = bind.execute(sa.select(sa.func.count()).select_from(questions).where(
        questions.c.subject_id == sid, questions.c.batch_id == BATCH
    )).scalar_one()
    if existing:
        raise RuntimeError(f"Unexpected existing {BATCH} questions: {existing}")

    slugs = dict(bind.execute(sa.select(canonical.c.chapter_num, canonical.c.slug).where(
        canonical.c.subject_id == sid, canonical.c.chapter_num.in_(tuple(ENRICHMENTS))
    )).all())
    now = datetime.utcnow()
    for item in QUESTIONS:
        number = item["chapter"]
        trace = {
            "source_label": "APSCHE enrichment MCQ",
            "source": "APSCHE History & Culture of Andhra (1512-1956)",
            "preservation": "appended_only_rr_hr_unchanged",
            "chapter_note_prefix_sha256": note_hashes[number],
            "review_status": "manual_source_comparison_pass",
        }
        values = {
            "subject_id": sid,
            "chapter_id": chapter_ids[number],
            "source_type": "chapter",
            "pyq_year": None,
            "pyq_paper": None,
            "difficulty": item["difficulty"],
            "question_en": "",
            "question_te": item["question"],
            "options_en": {key: "" for key in ("a", "b", "c", "d")},
            "options_te": item["options"],
            "correct_answer": item["answer"],
            "explanation_en": "",
            "explanation_te": item["explanation"] + "\n" + json.dumps(trace, ensure_ascii=False),
            "passage_id": None,
            "created_at": now,
            "updated_at": now,
            "syllabus_chapter_id": canonical_ids[number],
            "subtopic_id": None,
            "secondary_tags": {"chapter": number, "source_layer": "APSCHE_enrichment"},
            "source": "APSCHE",
            "source_file": "APSCHE Modern AP History Telugu PDF",
            "source_qid": item["qid"],
            "source_chapter": str(number),
            "qtype": item["qtype"],
            "review_status": "author_reviewed",
            "batch_id": BATCH,
            "content_hash": hashlib.md5((item["qid"] + item["question"]).encode("utf-8")).hexdigest(),
            "q_hash": hashlib.md5((item["question"] + json.dumps(item["options"], ensure_ascii=False, sort_keys=True)).encode("utf-8")).hexdigest(),
            "collection_id": None,
            "note_target_slug": slugs[number] + "-main",
            "source_trace": trace,
        }
        bind.execute(questions.insert().values(**_column_values(questions, values)))

    inserted = bind.execute(sa.select(sa.func.count()).select_from(questions).where(
        questions.c.subject_id == sid, questions.c.batch_id == BATCH
    )).scalar_one()
    if inserted != len(QUESTIONS):
        raise RuntimeError(f"Expected {len(QUESTIONS)} enrichment questions, got {inserted}")


def downgrade():
    bind = op.get_bind()
    meta = sa.MetaData()
    subjects = sa.Table("subjects", meta, autoload_with=bind)
    chapters = sa.Table("chapters", meta, autoload_with=bind)
    notes = sa.Table("notes", meta, autoload_with=bind)
    questions = sa.Table("questions", meta, autoload_with=bind)
    sid = bind.execute(sa.select(subjects.c.id).where(subjects.c.slug == "ap_history")).scalar_one()
    bind.execute(questions.delete().where(questions.c.subject_id == sid, questions.c.batch_id == BATCH))
    for number in ENRICHMENTS:
        chapter_id = bind.execute(sa.select(chapters.c.id).where(
            chapters.c.subject_id == sid, chapters.c.chapter_num == number
        )).scalar_one()
        note = bind.execute(sa.select(notes).where(notes.c.chapter_id == chapter_id).order_by(notes.c.section_num)).mappings().first()
        body = note["body_te"] or ""
        marker_at = body.find("\n\n" + MARKER)
        if marker_at < 0:
            raise RuntimeError(f"Cannot safely remove Chapter {number} enrichment")
        bind.execute(notes.update().where(notes.c.id == note["id"]).values(body_te=body[:marker_at]))
